package vn.gasstation.integration.seenpro.provider;
import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;import vn.gasstation.customer.application.CustomerProvider;import vn.gasstation.customer.domain.Customer;import vn.gasstation.integration.seenpro.client.SeenProHttpClient;import vn.gasstation.integration.seenpro.mapper.SeenProCustomerMapper;import vn.gasstation.integration.seenpro.parser.SeenProCustomerHtmlParser;
@Component @ConditionalOnProperty(name="app.data-source",havingValue="seenpro",matchIfMissing=true) public class SeenProCustomerAdapter implements CustomerProvider {private final SeenProHttpClient client;private final SeenProCustomerHtmlParser parser;private final SeenProCustomerMapper mapper;public SeenProCustomerAdapter(SeenProHttpClient client,SeenProCustomerHtmlParser parser,SeenProCustomerMapper mapper){this.client=client;this.parser=parser;this.mapper=mapper;}public List<Customer> findAll(){return parser.parse(client.get("khachhang.php",Map.of())).stream().map(mapper::map).toList();}}
